39	/**
40	 * This class is for maintaining  the various RPC statistics
41	 * and publishing them through the metrics interfaces.
42	 */
43	@InterfaceAudience.Private
44	@Metrics(about="Aggregate RPC metrics", context="rpc")
45	public class RpcMetrics {
46	
47	  static final Logger LOG = LoggerFactory.getLogger(RpcMetrics.class);
48	  final Server server;
49	  final MetricsRegistry registry;
50	  final String name;
51	  final boolean rpcQuantileEnable;
52	
53	  public static final TimeUnit DEFAULT_METRIC_TIME_UNIT =
54	      TimeUnit.MILLISECONDS;
55	  /** The time unit used when storing/accessing time durations. */
56	  private final TimeUnit metricsTimeUnit;
57	
58	  RpcMetrics(Server server, Configuration conf) {
59	    String port = String.valueOf(server.getListenerAddress().getPort());
60	    name = "RpcActivityForPort" + port;
61	    this.server = server;
62	    registry = new MetricsRegistry("rpc")
63	        .tag("port", "RPC port", port)
64	        .tag("serverName", "Name of the RPC server", server.getServerName());
65	    int[] intervals = conf.getInts(
66	        CommonConfigurationKeys.RPC_METRICS_PERCENTILES_INTERVALS_KEY);
67	    rpcQuantileEnable = (intervals.length > 0) && conf.getBoolean(
68	        CommonConfigurationKeys.RPC_METRICS_QUANTILE_ENABLE,
69	        CommonConfigurationKeys.RPC_METRICS_QUANTILE_ENABLE_DEFAULT);
70	    metricsTimeUnit = getMetricsTimeUnit(conf);
71	    if (rpcQuantileEnable) {
72	      rpcQueueTimeQuantiles =
73	          new MutableQuantiles[intervals.length];
74	      rpcLockWaitTimeQuantiles =
75	          new MutableQuantiles[intervals.length];
76	      rpcProcessingTimeQuantiles =
77	          new MutableQuantiles[intervals.length];
78	      deferredRpcProcessingTimeQuantiles =
79	          new MutableQuantiles[intervals.length];
80	      for (int i = 0; i < intervals.length; i++) {
81	        int interval = intervals[i];
82	        rpcQueueTimeQuantiles[i] = registry.newQuantiles("rpcQueueTime"
83	            + interval + "s", "rpc queue time in " + metricsTimeUnit, "ops",
84	            "latency", interval);
85	        rpcLockWaitTimeQuantiles[i] = registry.newQuantiles(
86	            "rpcLockWaitTime" + interval + "s",
87	            "rpc lock wait time in " + metricsTimeUnit, "ops",
88	            "latency", interval);
89	        rpcProcessingTimeQuantiles[i] = registry.newQuantiles(
90	            "rpcProcessingTime" + interval + "s",
91	            "rpc processing time in " + metricsTimeUnit, "ops",
92	            "latency", interval);
93	        deferredRpcProcessingTimeQuantiles[i] = registry.newQuantiles(
94	            "deferredRpcProcessingTime" + interval + "s",
95	            "deferred rpc processing time in " + metricsTimeUnit, "ops",
96	            "latency", interval);
97	      }
98	    }
99	    LOG.debug("Initialized " + registry);
100	  }
101	
102	  public String name() { return name; }
103	
104	  public static RpcMetrics create(Server server, Configuration conf) {
105	    RpcMetrics m = new RpcMetrics(server, conf);
106	    return DefaultMetricsSystem.instance().register(m.name, null, m);
107	  }
