153	  public static TimeUnit getMetricsTimeUnit(Configuration conf) {
154	    TimeUnit metricsTimeUnit = RpcMetrics.DEFAULT_METRIC_TIME_UNIT;
155	    String timeunit = conf.get(CommonConfigurationKeys.RPC_METRICS_TIME_UNIT);
156	    if (StringUtils.isNotEmpty(timeunit)) {
157	      try {
158	        metricsTimeUnit = TimeUnit.valueOf(timeunit);
159	      } catch (IllegalArgumentException e) {
160	        LOG.info("Config key {} 's value {} does not correspond to enum values"
161	                + " of java.util.concurrent.TimeUnit. Hence default unit"
162	                + " {} will be used",
163	            CommonConfigurationKeys.RPC_METRICS_TIME_UNIT, timeunit,
164	            RpcMetrics.DEFAULT_METRIC_TIME_UNIT);
165	      }
166	    }
167	    return metricsTimeUnit;
168	  }
